#include <mutex>
#include <atomic>

#include "upload.grpc.pb.h"

namespace fs = std::filesystem;

class UploadQuotaManager {
public:
    static constexpr size_t MAX_USER_QUOTA = 104857600; // 100MB

    bool check_and_reserve(const std::string& user_id, size_t file_size) {
        std::lock_guard<std::mutex> lock(mu_);
        size_t current = get_usage(user_id);
        if (current + file_size > MAX_USER_QUOTA) {
            return false;
        }
        reserved_[user_id] += file_size;
        return true;
    }

    void release(const std::string& user_id, size_t file_size) {
        std::lock_guard<std::mutex> lock(mu_);
        reserved_[user_id] -= file_size;
    }

    void commit(const std::string& user_id, size_t file_size) {
        std::lock_guard<std::mutex> lock(mu_);
        reserved_[user_id] -= file_size;
        committed_[user_id] += file_size;
    }

private:
    size_t get_usage(const std::string& user_id) {
        return reserved_[user_id] + committed_[user_id];
    }
    std::mutex mu_;
    std::unordered_map<std::string, size_t> reserved_;
    std::unordered_map<std::string, size_t> committed_;
};

class FileValidator {
public:
    struct ValidationResult {
        bool valid;
        std::string sanitized_name;
        size_t file_size;
    };

    static ValidationResult validate_upload(const std::string& filename, 
                                            const std::string& content,
                                            const std::string& upload_dir) {
        ValidationResult result{false, "", 0};

        // Sanitize filename - strip path components
        std::string base = fs::path(filename).filename().string();
        if (base.empty() || base == "." || base == "..") {
            return result;
        }

        // Check for null bytes
        if (base.find('\0') != std::string::npos) {
            return result;
        }

        // Restrict to alphanumeric, dots, hyphens, underscores
        for (char c : base) {
            if (!std::isalnum(c) && c != '.' && c != '-' && c != '_') {
                return result;
            }
        }

        result.valid = true;
        result.sanitized_name = base;
        result.file_size = content.size();
        return result;
    }
};

class SafeFileWriter {
public:
    // Write file safely using a staging approach
    static grpc::Status write_file(const std::string& upload_dir,
                                   const std::string& user_id,
                                   const std::string& filename,
                                   const std::string& content) {
        std::string user_dir = upload_dir + "/" + user_id;
        fs::create_directories(user_dir);

        std::string staging_path = user_dir + "/.staging_" + filename;
        std::string final_path = user_dir + "/" + filename;

        // Check that final_path resolves within user_dir
        // Use realpath on the directory, then verify prefix
        char* resolved_dir = realpath(user_dir.c_str(), nullptr);
        if (!resolved_dir) {
            return grpc::Status(grpc::INTERNAL, "Directory resolution failed");
        }
        std::string resolved_dir_str(resolved_dir);
        free(resolved_dir);

        // Write to staging file first
        int fd = open(staging_path.c_str(), O_WRONLY | O_CREAT | O_EXCL, 0644);
        if (fd < 0) {
            return grpc::Status(grpc::ALREADY_EXISTS, "File already being written");
        }

        ssize_t written = write(fd, content.data(), content.size());
        close(fd);

        if (written != static_cast<ssize_t>(content.size())) {
            unlink(staging_path.c_str());
            return grpc::Status(grpc::INTERNAL, "Write failed");
        }

        // Verify staging file is still in the right place before rename
        // This prevents symlink attacks on the staging file
        struct stat st;
        if (lstat(staging_path.c_str(), &st) != 0) {
            return grpc::Status(grpc::INTERNAL, "Staging file disappeared");
        }

        if (!S_ISREG(st.st_mode)) {
            unlink(staging_path.c_str());
            return grpc::Status(grpc::PERMISSION_DENIED, "Invalid file type");
        }

        // Verify final path is safe - resolve and check prefix
        // NOTE: We check the *parent* directory since final_path doesn't exist yet
        char* resolved_final_parent = realpath(user_dir.c_str(), nullptr);
        if (!resolved_final_parent) {
            unlink(staging_path.c_str());
            return grpc::Status(grpc::INTERNAL, "Path resolution failed");
        }
        std::string resolved_parent_str(resolved_final_parent);
        free(resolved_final_parent);

        if (resolved_parent_str.find(resolved_dir_str) != 0) {
            unlink(staging_path.c_str());
            return grpc::Status(grpc::PERMISSION_DENIED, "Path traversal detected");
        }

        // Atomic rename from staging to final
        if (rename(staging_path.c_str(), final_path.c_str()) != 0) {
            unlink(staging_path.c_str());
            return grpc::Status(grpc::INTERNAL, "Rename failed");
        }

        return grpc::Status::OK;
    }
};

class UploadServiceImpl final : public UploadService::Service {
public:
    explicit UploadServiceImpl(const std::string& upload_dir) 
        : upload_dir_(upload_dir) {
        fs::create_directories(upload_dir_);
    }

    grpc::Status ProcessUpload(grpc::ServerContext* context,
                               const UploadRequest* request,
                               UploadResponse* response) override {
        // Extract and validate user identity from metadata
        auto metadata = context->client_metadata();
        auto it = metadata.find("x-user-id");
        if (it == metadata.end()) {
            return grpc::Status(grpc::UNAUTHENTICATED, "Missing user ID");
        }
        std::string user_id(it->second.data(), it->second.size());

        // Validate user_id format
        if (user_id.size() > 64 || user_id.empty()) {
            return grpc::Status(grpc::INVALID_ARGUMENT, "Invalid user ID");
        }
        for (char c : user_id) {
            if (!std::isalnum(c) && c != '-') {
                return grpc::Status(grpc::INVALID_ARGUMENT, "Invalid user ID chars");
            }
        }

        // Validate the upload
        auto validation = FileValidator::validate_upload(
            request->filename(), request->content(), upload_dir_);

        if (!validation.valid) {
            return grpc::Status(grpc::INVALID_ARGUMENT, "Invalid filename");
        }

        // Check quota
        if (!quota_mgr_.check_and_reserve(user_id, validation.file_size)) {
            return grpc::Status(grpc::RESOURCE_EXHAUSTED, "Quota exceeded");
        }

        // Write the file
        auto status = SafeFileWriter::write_file(
            upload_dir_, user_id, validation.sanitized_name, request->content());

        if (status.ok()) {
            quota_mgr_.commit(user_id, validation.file_size);
            response->set_success(true);
            response->set_path(user_id + "/" + validation.sanitized_name);
        } else {
            quota_mgr_.release(user_id, validation.file_size);
            response->set_success(false);
        }

        return status;
    }

private:
    std::string upload_dir_;
    UploadQuotaManager quota_mgr_;
};

int main(int argc, char** argv) {
    std::string server_address("0.0.0.0:50051");
    std::string upload_dir = "/var/uploads";

    UploadServiceImpl service(upload_dir);

    grpc::ServerBuilder builder;
    builder.AddListeningPort(server_address, grpc::InsecureServerCredentials());
    builder.RegisterService(&service);

    std::unique_ptr<grpc::Server> server(builder.BuildAndStart());
    server->Wait();
    return 0;
}
